svg.script:
(function () {
  var root = document.getElementById("static-scramjet-root");
  var frame = document.createElementNS("http://www.w3.org/1999/xhtml", "iframe");
  frame.setAttribute("allow", "autoplay; fullscreen; clipboard-read; clipboard-write; encrypted-media; picture-in-picture; gamepad");
  frame.setAttribute("style", "position:fixed;inset:0;width:100%;height:100%;border:0;margin:0;padding:0;display:block;background:#0d1324;");

  function fromBase64(payload) {
    return new TextDecoder().decode(Uint8Array.from(atob(payload), function (char) {
      return char.charCodeAt(0);
    }));
  }

  var params = new URLSearchParams(location.search);
  var html = fromBase64("");
  var inject = "<script>" +
    "window.__AETHER_STATIC_SCRAMJET_HREF__=" + JSON.stringify(window.location.href).replace(/</g, "\u003c") + ";" +
    "window.__AETHER_STATIC_WISP=" + JSON.stringify(params.get("wisp") || "").replace(/</g, "\u003c") + ";" +
    "window.__AETHER_STATIC_BACKEND=" + JSON.stringify(params.get("backend") || "scramjet2").replace(/</g, "\u003c") + ";" +
    "window.__AETHER_STATIC_TARGET_HASH=" + JSON.stringify(location.hash.slice(1)).replace(/</g, "\u003c") + ";" +
    "<\/script>";

  if (/<\/head>/i.test(html)) {
    html = html.replace(/<\/head>/i, inject + "</head>");
  } else {
    html = inject + html;
  }

  frame.src = URL.createObjectURL(new Blob([html], { type: "text/html" }));
  root.appendChild(frame);
})();
